local currentTheme = "Bento"
local C = {}
local function applyTheme(name)
    if not THEMES[name] then name = "Bento" end
    currentTheme = name
    for k, v in pairs(THEMES[name]) do C[k] = v end
end
applyTheme("Bento")

local Motion = {
    fast = TweenInfo.new(0.10, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
    base = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
    smooth = TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
    spring = TweenInfo.new(0.32, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
}

local function make(className, props, parent)
    local obj = Instance.new(className)
    if props then
        for k, v in pairs(props) do
            pcall(function() obj[k] = v end)
        end
    end
    if parent then obj.Parent = parent end
    return obj
end

local function corner(parent, r)
    return make("UICorner", {CornerRadius = UDim.new(0, r or 12)}, parent)
end

local function outline(parent, color, transparency, thickness)
    return make("UIStroke", {
        Color = color or C.line,
        Transparency = transparency == nil and 0.42 or transparency,
        Thickness = thickness or 1,
    }, parent)
end

local function pad(parent, l, r, t, b)
    return make("UIPadding", {
        PaddingLeft = UDim.new(0, l or 0), PaddingRight = UDim.new(0, r or 0),
        PaddingTop = UDim.new(0, t or 0), PaddingBottom = UDim.new(0, b or 0),
    }, parent)
end

local function list(parent, gap)
    local lay = make("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, gap or 8),
    }, parent)
    return lay
end

local function tween(obj, info, props)
    if not obj or not obj.Parent then return end
    local ok, tw = pcall(function() return TweenService:Create(obj, info or Motion.base, props) end)
    if ok and tw then tw:Play(); return tw end
end

local function text(parent, value, size, color, bold)
    return make("TextLabel", {
        BackgroundTransparency = 1, BorderSizePixel = 0, Text = tostring(value or ""),
        TextColor3 = color or C.text, TextSize = size or 13,
        Font = bold and Enum.Font.GothamMedium or Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, parent)
end

local function hitButton(parent, z)
    return make("TextButton", {
        Text = "", BackgroundTransparency = 1, BorderSizePixel = 0,
        AutoButtonColor = false, Size = UDim2.fromScale(1, 1), ZIndex = z or 50,
    }, parent)
end

local function safeName(s)
    return tostring(s or "Element"):gsub("[^%w_]+", "_")
end

local function isTouchDevice()
    return UserInputService.TouchEnabled == true
end

local function getViewport()
    local cam = workspace.CurrentCamera
    return cam and cam.ViewportSize or Vector2.new(1280, 720)
end

local function isMobile()
    local vp = getViewport()
    return vp.X < 720 or (isTouchDevice() and vp.X < 960)
end

