-- ============================================================
local PACKED_ICONS = {
    ["x"] = "",
    ["minus"] = "",
    ["plus"] = "",
    ["chevron-down"] = "",
    ["chevron-right"] = "",
    ["check"] = "",
    ["circle-check"] = "",
    ["play"] = "",
    ["settings"] = "",
    ["search"] = "",
    ["info"] = "",
    ["house"] = "",
    ["layout-dashboard"] = "",
    ["panel-left"] = "",
    ["panels-top-left"] = "",
    ["fish"] = "",
    ["fishing-rod"] = "",
    ["hand-heart"] = "",
    ["flame"] = "",
    ["swords"] = "",
    ["shopping-bag"] = "",
    ["shopping-cart"] = "",
    ["store"] = "",
    ["repeat-2"] = "",
    ["scroll-text"] = "",
    ["trending-up"] = "",
    ["map-pin"] = "",
    ["ship"] = "",
    ["user"] = "",
    ["user-round"] = "",
    ["users-round"] = "",
    ["lock"] = "",
    ["shield-alert"] = "",
    ["shield"] = "",
    ["eye-off"] = "",
    ["copy"] = "",
    ["external-link"] = "",
    ["message-circle"] = "",
    ["music-2"] = "",
    ["sparkles"] = "",
    ["shapes"] = "",
    ["zap"] = "",
    ["volleyball"] = "",
}

local PACK_ALIASES = {
    dashboard="layout-dashboard", layout="layout-dashboard", overview="layout-dashboard", home="house",
    config="panel-left", tune="panel-left", close="x", remove="minus", add="plus", next="chevron-right",
    expand="chevron-down", cancel="x", back="chevron-right", warning="shield-alert", success="circle-check",
    player="user-round", players="users-round", settings="settings", update="history", discord="message-circle",
}

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function decodePacked(value)
    local out = {}
    local acc = 0
    local bits = 0
    for i = 1, #value do
        local c = value:sub(i, i)
        if c ~= "=" then
            local pos = B64:find(c, 1, true)
            if pos then
                acc = acc * 64 + (pos - 1)
                bits = bits + 6
                while bits >= 8 do
                    bits = bits - 8
                    local byte = math.floor(acc / (2 ^ bits)) % 256
                    out[#out + 1] = string.char(byte)
                    acc = acc % (2 ^ bits)
                end
            end
        end
    end
    return table.concat(out)
end

local function normalizeIconName(name)
    local key = string.lower(tostring(name or "circle")):gsub("%s+", "-")
    return PACK_ALIASES[key] or key
end

local function fallbackPixelIcon(parent, name, position, size, color, z)
    local holder = make("Frame", {
        Name = "PackedPixelFallback", BackgroundTransparency = 1, BorderSizePixel = 0,
        Position = position or UDim2.fromOffset(0, 0), Size = size or UDim2.fromOffset(20, 20),
        ZIndex = z or 5,
    }, parent)
    local data = decodePacked(PACKED_ICONS[normalizeIconName(name)] or PACKED_ICONS["circle-check"] or "")
    if #data < 576 then return holder end

    -- Lightweight raster fallback: compress each bitmap row into contiguous alpha runs.
    -- This preserves anti-aliased alpha without creating a 24x24 Frame grid.
    for y = 0, 23 do
        local x = 0
        while x < 24 do
            local a = string.byte(data, y * 24 + x + 1) or 0
            if a > 10 then
                local startX = x
                local sum = a
                local count = 1
                x = x + 1
                while x < 24 do
                    local nextA = string.byte(data, y * 24 + x + 1) or 0
                    if nextA <= 10 then break end
                    sum = sum + nextA
                    count = count + 1
                    x = x + 1
                end
                local avg = sum / count
                local alphaTransparency = 1 - math.clamp(avg / 255, 0, 1)
                local pixel = make("Frame", {
                    BackgroundColor3 = color or C.muted,
                    BackgroundTransparency = alphaTransparency,
                    BorderSizePixel = 0,
                    Position = UDim2.new(startX / 24, 0, y / 24, 0),
                    Size = UDim2.new(count / 24, 0, 1 / 24, 0),
                    ZIndex = z or 5,
                }, holder)
                pixel:SetAttribute("KhfreshOriginalTransparency", alphaTransparency)
            else
                x = x + 1
            end
        end
    end
    return holder
end

local function packedIcon(parent, name, position, size, color, z)
    local holder = make("Frame", {
        Name = "PackedIcon_" .. safeName(name), BackgroundTransparency = 1, BorderSizePixel = 0,
        Position = position or UDim2.fromOffset(0, 0), Size = size or UDim2.fromOffset(20, 20),
        ZIndex = z or 5,
    }, parent)
    local packed = PACKED_ICONS[normalizeIconName(name)]
    if not packed then
        pcall(function() holder:Destroy() end)
        return fallbackPixelIcon(parent, "circle", position, size, color, z)
    end

    local decoded = decodePacked(packed)
    local usedEditable = false
    local bufferAvailable, rawBuffer = pcall(function() return buffer.create(24 * 24 * 4) end)
    if bufferAvailable and rawBuffer then
        local ok, editable = pcall(function()
            return AssetService:CreateEditableImage({Size = Vector2.new(24, 24)})
        end)
        if ok and editable then
            local buf = rawBuffer
            for i = 1, 576 do
                local a = string.byte(decoded, i) or 0
                local o = (i - 1) * 4
                buffer.writeu8(buf, o, 255)
                buffer.writeu8(buf, o + 1, 255)
                buffer.writeu8(buf, o + 2, 255)
                buffer.writeu8(buf, o + 3, a)
            end
            local wrote = pcall(function()
                editable:WritePixelsBuffer(Vector2.zero, Vector2.new(24, 24), buf)
            end)
            local contentValue = nil
            if wrote then
                pcall(function()
                    local contentType = rawget(_G, "Content")
                    if contentType and type(contentType.fromObject) == "function" then
                        contentValue = contentType.fromObject(editable)
                    end
                end)
            end
            if contentValue ~= nil then
                local image = make("ImageLabel", {
                    Name = "PackedBitmap", BackgroundTransparency = 1, BorderSizePixel = 0,
                    Size = UDim2.fromScale(1, 1), ImageContent = contentValue,
                    ImageColor3 = color or C.muted, ScaleType = Enum.ScaleType.Fit, ZIndex = z or 5,
                }, holder)
                table.insert(UI._iconImages, editable)
                usedEditable = image ~= nil
            else
                pcall(function() editable:Destroy() end)
            end
        end
    end
    if not usedEditable then
        holder:Destroy()
        return fallbackPixelIcon(parent, name, position, size, color, z)
    end
    return holder
end

local function iconSetColor(icon, color)
    if not icon then return end
    local image = icon:FindFirstChild("PackedBitmap")
    if image and image:IsA("ImageLabel") then
        image.ImageColor3 = color
    else
        for _, obj in ipairs(icon:GetDescendants()) do
            if obj:IsA("Frame") and obj ~= icon then obj.BackgroundColor3 = color end
        end
    end
end

-- ============================================================
-- WINDOW / TAB / SECTION
-- ============================================================
local Window = {}
Window.__index = Window
local Tab = {}
Tab.__index = Tab
local Section = {}
Section.__index = Section

local function updateSectionHeight(section)
    if not section or not section._frame or not section._body or not section._layout then return end
    local bodyH = section._layout.AbsoluteContentSize.Y
    section._body.Size = UDim2.new(1, 0, 0, bodyH)
    section._frame.Size = UDim2.new(1, 0, 0, 45 + bodyH + 12)
end

local function updateColumnHeight(column, layout)
    if not column or not layout then return end
    column.Size = UDim2.new(column.Size.X.Scale, column.Size.X.Offset, 0, layout.AbsoluteContentSize.Y)
end

local function buildSectionHost(tab)
    tab._headerHost = make("Frame", {
        Name = "HeaderHost", BackgroundTransparency = 1, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    }, tab._page)
    tab._headerLayout = list(tab._headerHost, 5)
    tab._headerHost.LayoutOrder = 1

    if tab._settingsBento then
        tab._grid = make("Frame", {
            Name = "BentoGrid", BackgroundTransparency = 1, BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2,
        }, tab._page)
        tab._left = make("Frame", {
            Name = "LeftColumn", BackgroundTransparency = 1, BorderSizePixel = 0,
            Size = UDim2.new(0.5, -6, 0, 0),
        }, tab._grid)
        tab._right = make("Frame", {
            Name = "RightColumn", BackgroundTransparency = 1, BorderSizePixel = 0,
            Size = UDim2.new(0.5, -6, 0, 0), Position = UDim2.new(0.5, 6, 0, 0),
        }, tab._grid)
        tab._leftLayout = list(tab._left, 10)
        tab._rightLayout = list(tab._right, 10)
        tab._settingsLeftConn = tab._leftLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            updateColumnHeight(tab._left, tab._leftLayout)
            updateColumnHeight(tab._right, tab._rightLayout)
            local h = math.max(tab._leftLayout.AbsoluteContentSize.Y, tab._rightLayout.AbsoluteContentSize.Y)
            tab._grid.Size = UDim2.new(1, 0, 0, h)
        end)
        tab._settingsRightConn = tab._rightLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            updateColumnHeight(tab._left, tab._leftLayout)
            updateColumnHeight(tab._right, tab._rightLayout)
            local h = math.max(tab._leftLayout.AbsoluteContentSize.Y, tab._rightLayout.AbsoluteContentSize.Y)
            tab._grid.Size = UDim2.new(1, 0, 0, h)
        end)
        return tab._grid
    end

    tab._listHost = make("Frame", {
        Name = "ElementHost", BackgroundTransparency = 1, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2,
    }, tab._page)
    tab._elementLayout = list(tab._listHost, 10)
    return tab._listHost
end

function UI:SetTheme(name)
    applyTheme(name)
    for _, win in ipairs(UI._windows) do
        if win.ApplyTheme then pcall(function() win:ApplyTheme() end) end
    end
end
function UI:GetTheme() return currentTheme end
function UI:GetThemes() return {"Bento", "Dark"} end

function UI:Notify(config)
    config = config or {}
    if not self._notifyGui or not self._notifyGui.Parent then
        self._notifyGui = make("ScreenGui", {
            Name = "KhfreshNotify", ResetOnSpawn = false, IgnoreGuiInset = true,
            DisplayOrder = 2147483640, ZIndexBehavior = Enum.ZIndexBehavior.Global,
        }, GuiParent)
        local wrap = make("Frame", {Name = "Wrapper", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1)}, self._notifyGui)
        local lay = list(wrap, 8)
        lay.HorizontalAlignment = Enum.HorizontalAlignment.Right
        lay.VerticalAlignment = Enum.VerticalAlignment.Bottom
        pad(wrap, 0, 16, 0, 16)
    end
    local wrap = self._notifyGui.Wrapper
    local mobile = isMobile()
    local card = make("Frame", {
        BackgroundColor3 = C.shell, BorderSizePixel = 0,
        Size = UDim2.fromOffset(mobile and 270 or 320, 72), LayoutOrder = -math.floor(os.clock() * 1000),
    }, wrap)
    corner(card, 16); outline(card, C.line, 0.2, 1)
    packedIcon(card, config.Icon or "info", UDim2.fromOffset(14, 18), UDim2.fromOffset(26, 26), C.accent, 5)
    local t = text(card, config.Title or "Khfresh", 13, C.text, true)
    t.Position = UDim2.fromOffset(50, 9); t.Size = UDim2.new(1, -60, 0, 20)
    local d = text(card, config.Content or config.Message or "", 11, C.secondary, false)
    d.Position = UDim2.fromOffset(50, 31); d.Size = UDim2.new(1, -60, 0, 32); d.TextWrapped = true
    task.delay(tonumber(config.Duration) or 3, function()
        if card.Parent then
            tween(card, Motion.fast, {BackgroundTransparency = 1})
            task.wait(0.12)
            pcall(function() card:Destroy() end)
        end
    end)
end

local function clampWindowSize(requested)
    local vp = getViewport()
    local mobile = isMobile()
    local minW = mobile and 292 or 540
    local minH = mobile and 350 or 430
    local maxW = math.max(minW, vp.X - (mobile and 10 or 28))
    local maxH = math.max(minH, vp.Y - (mobile and 10 or 28))
    local w = requested and requested.X.Offset or 760
    local h = requested and requested.Y.Offset or 540
    if mobile then
        w = math.min(maxW, math.max(minW, w))
        h = math.min(maxH, math.max(minH, h))
    else
        w = math.min(maxW, math.max(minW, w))
        h = math.min(maxH, math.max(minH, h))
    end
    return UDim2.fromOffset(w, h)
end

local function installMove(win)
    local shell = win._shell
    local handle = win._dragHandle
    local dragging = false
    local startInput = nil
    local startPos = nil

    local function begin(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        dragging = true
        startInput = input.Position
        startPos = shell.Position
        win._moving = true
    end
    local function endMove(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
            win._moving = false
        end
    end
    handle.InputBegan:Connect(begin)
    table.insert(win._connections, UserInputService.InputEnded:Connect(endMove))
    table.insert(win._connections, UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = input.Position - startInput
        shell.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end))
end

local function installResize(win)
    local shell = win._shell
    local grip = win._resizeHandle
    local resizing = false
    local startInput, startSize = nil, nil
    grip.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        resizing = true
        startInput = input.Position
        startSize = shell.AbsoluteSize
    end)
    table.insert(win._connections, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then resizing = false end
    end))
    table.insert(win._connections, UserInputService.InputChanged:Connect(function(input)
        if not resizing then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local d = input.Position - startInput
        local vp = getViewport()
        local mobile = isMobile()
        local minW = mobile and 292 or 540
        local minH = mobile and 350 or 430
        local maxW = math.max(minW, vp.X - (mobile and 8 or 20))
        local maxH = math.max(minH, vp.Y - (mobile and 8 or 20))
        local w = math.clamp(startSize.X + d.X, minW, maxW)
        local h = math.clamp(startSize.Y + d.Y, minH, maxH)
        shell.Size = UDim2.fromOffset(w, h)
        win._manualSize = shell.Size
        win:_refreshLayout()
    end))
end

function Window:_refreshLayout()
    local mobile = isMobile()
    self._mobile = mobile
    local topH = mobile and 68 or 82
    self._top.Size = UDim2.new(1, 0, 0, topH)
    self._rail.Position = UDim2.fromOffset(0, topH)
    self._rail.Size = UDim2.new(0, mobile and 64 or self._railWidth, 1, -topH)
    self._content.Position = UDim2.fromOffset(mobile and 64 or self._railWidth, topH)
    self._content.Size = UDim2.new(1, -(mobile and 64 or self._railWidth), 1, -topH)
    self._dragHandle.Position = UDim2.new(0.5, -80, 1, -20)
    self._dragHandle.Size = UDim2.fromOffset(190, 20)
    self._logoHolder.Size = UDim2.fromOffset(mobile and 46 or 54, mobile and 46 or 54)
    self._logoHolder.Position = UDim2.fromOffset(12, mobile and 9 or 14)
    if self._logo then
        self._logo.Size = UDim2.fromScale(1, 1)
    end
    self._brandText.Visible = not mobile
    self._authorText.Visible = not mobile
    self._minBtn.Position = UDim2.new(1, mobile and -84 or -86, 0, mobile and 17 or 24)
    self._closeBtn.Position = UDim2.new(1, mobile and -44 or -44, 0, mobile and 17 or 24)
    for _, tab in ipairs(self._tabs) do
        tab._label.Visible = not mobile
        tab._btn.Size = UDim2.new(1, 0, 0, mobile and 46 or 48)
        if mobile then
            tab._icon.Position = UDim2.new(0.5, -12, 0.5, -12)
        else
            tab._icon.Position = UDim2.fromOffset(12, 12)
        end
    end
    if self._settingsTab then
        local tab = self._settingsTab
        local width = self._content.AbsoluteSize.X
        local useSingle = mobile or width < 560
        if useSingle then
            tab._left.Size = UDim2.new(1, 0, 0, 0)
            tab._right.Size = UDim2.new(1, 0, 0, 0)
            for _, sec in ipairs(tab._sections) do
                sec._frame.Parent = tab._left
                sec._frame.LayoutOrder = sec._order
            end
            tab._right.Visible = false
            tab._left.Visible = true
        else
            tab._right.Visible = true
            for _, sec in ipairs(tab._sections) do
                sec._frame.Parent = sec._desktopParent or tab._left
            end
        end
    end
end

function UI:CreateWindow(config)
    config = config or {}
    local win = setmetatable({
        _requestedSize = config.Size or UDim2.fromOffset(760, 540),
        _railWidth = 178, _tabs = {}, _connections = {}, _open = true, _tabSequence = 0,
        _selected = nil, _settingsTab = nil,
    }, Window)

    local old = GuiParent:FindFirstChild("KhfreshBentoUI")
    if old then pcall(function() old:Destroy() end) end

    local gui = make("ScreenGui", {
        Name = "KhfreshBentoUI", ResetOnSpawn = false, IgnoreGuiInset = true,
        DisplayOrder = 2147483645, ZIndexBehavior = Enum.ZIndexBehavior.Global,
    }, GuiParent)
    pcall(function() if syn and syn.protect_gui then syn.protect_gui(gui) end end)
    win._gui = gui

    local shell = make("Frame", {
        Name = "Shell", BackgroundColor3 = C.canvas, BorderSizePixel = 0,
        Size = clampWindowSize(win._requestedSize), Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5), ClipsDescendants = true, Active = true,
    }, gui)
    corner(shell, 24); outline(shell, C.line, 0.26, 1)
    win._shell = shell

    if type(config.Background) == "string" and config.Background ~= "" then
        win._background = make("ImageLabel", {
            Name = "Background", BackgroundTransparency = 1, BorderSizePixel = 0,
