            Rotation = -45, ZIndex = 101,
        }, win._resizeHandle)
        line.AnchorPoint = Vector2.new(1, 0.5)
    end

    table.insert(UI._windows, win)
    installMove(win)
    installResize(win)

    win._cameraConnection = nil
    local camera = workspace.CurrentCamera
    if camera then
        win._cameraConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
            local oldSize = win._manualSize
            if oldSize then win._shell.Size = clampWindowSize(oldSize) else win._shell.Size = clampWindowSize(win._requestedSize) end
            win:_refreshLayout()
        end)
        table.insert(win._connections, win._cameraConnection)
    end
    win:_refreshLayout()
    gui.Enabled = true
    shell.Visible = true
    return win
end

function Window:CreateTab(nameOrConfig, icon)
    local config = type(nameOrConfig) == "table" and nameOrConfig or {Title = nameOrConfig, Icon = icon}
    local title = tostring(config.Title or config.Name or "Tab")
    local iconName = config.Icon or "circle"
    self._tabSequence = self._tabSequence + 1

    local btn = make("TextButton", {
        Name = "Tab_" .. safeName(title), Text = "", BackgroundColor3 = C.row, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 48), AutoButtonColor = false, LayoutOrder = self._tabSequence, ZIndex = 17,
    }, self._rail)
    corner(btn, 15)
    local ico = packedIcon(btn, iconName, UDim2.fromOffset(12, 12), UDim2.fromOffset(24, 24), C.muted, 18)
    local lbl = text(btn, title, 12, C.secondary, true)
    lbl.Position = UDim2.fromOffset(46, 0); lbl.Size = UDim2.new(1, -54, 1, 0); lbl.ZIndex = 19

    local page = make("ScrollingFrame", {
        Name = "Page_" .. safeName(title), BackgroundTransparency = 1, BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollBarThickness = 4, ScrollBarImageColor3 = C.muted, ScrollingDirection = Enum.ScrollingDirection.Y,
        Visible = false, ZIndex = 12, ClipsDescendants = false,
    }, self._content)
    page.ScrollingEnabled = true
    page.AutomaticCanvasSize = Enum.AutomaticSize.Y
    local pageLayout = make("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 10),
    }, page)
    pageLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    pad(page, 16, 16, 16, 34)

    local tab = setmetatable({
        _window = self, _btn = btn, _icon = ico, _label = lbl, _page = page,
        _title = title, _iconName = iconName, _order = 0, _sections = {}, _settingsBento = string.lower(title) == "settings",
    }, Tab)
    pageLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        page.CanvasSize = UDim2.new(0, 0, 0, pageLayout.AbsoluteContentSize.Y + 24)
    end)
    table.insert(self._tabs, tab)
    if tab._settingsBento then self._settingsTab = tab end
    buildSectionHost(tab)

    btn.Activated:Connect(function() self:SelectTab(tab) end)
    if #self._tabs == 1 then self:SelectTab(tab) end
    self:_refreshLayout()
    return tab
end

function Window:GetTab(title)
    local wanted = string.lower(tostring(title or ""))
    for _, tab in ipairs(self._tabs) do
        if string.lower(tab._title) == wanted then return tab end
    end
end

function Window:SelectTab(index)
    local tab = type(index) == "table" and index or self._tabs[tonumber(index) or 1]
    if not tab then return end
    if ActiveDropdown then pcall(function() ActiveDropdown:Destroy() end); ActiveDropdown = nil end
    self._selected = tab
    for _, t in ipairs(self._tabs) do
        local on = t == tab
        t._page.Visible = on
        t._btn.BackgroundColor3 = on and C.lineSoft or C.row
        t._label.TextColor3 = on and C.text or C.secondary
        iconSetColor(t._icon, on and C.secondary or C.muted)
    end
end

function Window:Toggle()
    self._open = not self._open
    if self._open then
        self._shell.Visible = true
        self._shell.BackgroundTransparency = 0.08
        tween(self._shell, Motion.smooth, {BackgroundTransparency = 0})
    else
        tween(self._shell, Motion.fast, {BackgroundTransparency = 0.08})
        task.delay(0.11, function()
            if not self._open and self._shell then self._shell.Visible = false end
        end)
    end
end
function Window:Minimize() self._open = false; self._shell.Visible = false end
function Window:Open() self._open = true; self._shell.Visible = true end
function Window:Destroy()
    for _, c in ipairs(self._connections or {}) do pcall(function() c:Disconnect() end) end
    for _, t in ipairs(self._tabs or {}) do
        pcall(function() if t._settingsLeftConn then t._settingsLeftConn:Disconnect() end end)
        pcall(function() if t._settingsRightConn then t._settingsRightConn:Disconnect() end end)
    end
    if #UI._windows <= 1 then
        for _, image in ipairs(UI._iconImages) do pcall(function() image:Destroy() end) end
        table.clear(UI._iconImages)
    end
    if self._floatingGui then pcall(function() self._floatingGui:Destroy() end) end
    if self._gui then pcall(function() self._gui:Destroy() end) end
    for i, v in ipairs(UI._windows) do if v == self then table.remove(UI._windows, i); break end end
end
function Window:ToggleAcrylic() end
function Window:SetBackground(asset, transparency)
    if not self._background then
        self._background = make("ImageLabel", {Name = "Background", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ScaleType = Enum.ScaleType.Crop, ZIndex = 0}, self._shell)
        self._backgroundTint = make("Frame", {Name = "BackgroundTint", BackgroundColor3 = Color3.fromRGB(8, 10, 14), BackgroundTransparency = 0.74, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 1}, self._shell)
    end
    self._background.Image = tostring(asset or "")
    self._background.ImageTransparency = tonumber(transparency) or 0.42
end
function Window:SetLogo(asset)
    if self._logo then self._logo:Destroy() end
    self._logo = make("ImageLabel", {Name = "Logo", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Image = tostring(asset or ""), ScaleType = Enum.ScaleType.Fit, ZIndex = 23}, self._logoHolder)
end
function Window:_setFloatingVisible(show, immediate)
    local sg = self._floatingGui
    local btn = self._floatingButton
    if not sg or not sg.Parent or not btn then
        self._floatingVisible = show == true
        return
    end
    self._floatingVisible = show == true
    if show then
        sg.Enabled = true
        btn.BackgroundTransparency = 1
        local scale = btn:FindFirstChildOfClass("UIScale")
        if scale then scale.Scale = immediate and 1 or 0.82 end
        local iconHolder = btn:FindFirstChildOfClass("Frame")
        if immediate then
            btn.BackgroundTransparency = 0
            if scale then scale.Scale = 1 end
        else
            tween(btn, Motion.smooth, {BackgroundTransparency = 0})
            if scale then tween(scale, Motion.spring, {Scale = 1}) end
            if iconHolder then
                for _, obj in ipairs(iconHolder:GetDescendants()) do
                    if obj:IsA("ImageLabel") then obj.ImageTransparency = 1; tween(obj, Motion.smooth, {ImageTransparency = 0}) end
                    if obj:IsA("Frame") then
                        local original = obj:GetAttribute("KhfreshOriginalTransparency")
                        if original ~= nil then
                            obj.BackgroundTransparency = 1
                            tween(obj, Motion.smooth, {BackgroundTransparency = original})
                        end
                    end
                end
            end
        end
    else
        local scale = btn:FindFirstChildOfClass("UIScale")
        if immediate then
            if scale then scale.Scale = 0.82 end
            btn.BackgroundTransparency = 1
            sg.Enabled = false
            return
        end
        tween(btn, Motion.fast, {BackgroundTransparency = 1})
        if scale then tween(scale, Motion.fast, {Scale = 0.82}) end
        task.delay(0.14, function()
            if self._floatingVisible == false and sg.Parent then sg.Enabled = false end
        end)
    end
end

function Window:SetFloatingVisible(v)
    self:_setFloatingVisible(v ~= false, false)
end

function Window:CreateFloatingToggle(config)
    config = config or {}
    if self._floatingGui then pcall(function() self._floatingGui:Destroy() end) end
    local sg = make("ScreenGui", {
        Name = "KhfreshFloatingGui", ResetOnSpawn = false, IgnoreGuiInset = true,
        DisplayOrder = 2147483630, ZIndexBehavior = Enum.ZIndexBehavior.Global,
    }, GuiParent)
    self._floatingGui = sg
    self._floatingVisible = true
    local mobile = isMobile()
    local size = mobile and 50 or 54
    local btn = make("TextButton", {
        Name = "FloatingButton", Text = "", BackgroundColor3 = C.header, BorderSizePixel = 0,
        Size = UDim2.fromOffset(size, size), Position = UDim2.new(1, -(size + 16), 1, -(size + 18)),
        AutoButtonColor = false, Active = true, ZIndex = 10, BackgroundTransparency = 1,
    }, sg)
    corner(btn, mobile and 16 or 17); outline(btn, C.lineSoft, 0.18, 1)
    self._floatingButton = btn
    local iconHolder = packedIcon(btn, config.Icon or "volleyball", UDim2.fromOffset(size * 0.20, size * 0.20), UDim2.fromOffset(size * 0.60, size * 0.60), C.secondary, 12)
    local scale = make("UIScale", {Scale = 0.82}, btn)
    btn.Activated:Connect(function() self:Toggle() end)
    local function reposition()
        if not btn or not btn.Parent then return end
        local m = isMobile()
        local sz = m and 50 or 54
        btn.Size = UDim2.fromOffset(sz, sz)
        btn.Position = UDim2.new(1, -(sz + 16), 1, -(sz + 18))
    end
    local camera = workspace.CurrentCamera
    if camera then table.insert(self._connections, camera:GetPropertyChangedSignal("ViewportSize"):Connect(reposition)) end
    self:_setFloatingVisible(true, false)
    return sg
end

function Tab:CreateHeader(config)
    config = type(config) == "table" and config or {Title = tostring(config or "")}
    self._headerSeq = (self._headerSeq or 0) + 1
    local frame = make("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 54), LayoutOrder = self._headerSeq}, self._headerHost)
    if config.Icon then packedIcon(frame, config.Icon, UDim2.fromOffset(0, 15), UDim2.fromOffset(20, 20), C.accent, 5) end
    local left = config.Icon and 28 or 0
    local t = text(frame, config.Title or "", 17, C.text, true); t.Position = UDim2.fromOffset(left, 0); t.Size = UDim2.new(1, -left, 0, 28)
    local s = text(frame, config.Subtitle or config.Desc or "", 11, C.muted, false); s.Position = UDim2.fromOffset(left, 29); s.Size = UDim2.new(1, -left, 0, 20)
    return frame
end

function Tab:_chooseParent(section)
    if not self._settingsBento then return self._listHost end
    local vp = getViewport()
    local mobile = isMobile() or self._window._content.AbsoluteSize.X < 560
    if mobile then return self._left end
    if section._side == "right" then return self._right end
    if section._side == "left" then return self._left end
    local count = #self._sections
    return (count % 2 == 1) and self._left or self._right
end

function Tab:_moveSettingsSections()
    if not self._settingsBento then return end
    local mobile = isMobile() or self._window._content.AbsoluteSize.X < 560
    if mobile then
        self._right.Visible = false
        self._left.Visible = true
        for _, section in ipairs(self._sections) do
            section._frame.Parent = self._left
            section._frame.LayoutOrder = section._sectionOrder
        end
    else
        self._right.Visible = true
        for _, section in ipairs(self._sections) do
            section._frame.Parent = section._desktopParent or self._left
        end
    end
end

function Tab:_directSection()
    if self._direct then return self._direct end
    local s = self:CreateSection({Title = "", HideHeader = true})
    self._direct = s
    return s
end

function Tab:CreateSection(nameOrConfig, side)
    local config = type(nameOrConfig) == "table" and nameOrConfig or {Title = nameOrConfig, Side = side}
    local name = tostring(config.Title or config.Name or "Section")
    local sideName = type(config.Side) == "string" and string.lower(config.Side) or nil
    self._order = (self._order or 0) + 1

    local frame = make("Frame", {
        Name = "Section_" .. safeName(name), BackgroundColor3 = C.card, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 57), ClipsDescendants = false, LayoutOrder = self._order, ZIndex = 30,
    }, nil)
    if self._settingsBento then
        corner(frame, 18); outline(frame, C.lineSoft, 0.14, 1)
    else
        frame.BackgroundTransparency = 1
    end

    local header = make("Frame", {Name = "SectionHeader", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 45), ZIndex = 31}, frame)
    if not config.HideHeader and name ~= "" then
        packedIcon(header, config.Icon or "shapes", UDim2.fromOffset(12, 13), UDim2.fromOffset(19, 19), C.muted, 34)
        local title = text(header, name, 13, C.text, true)
        title.Position = UDim2.fromOffset(40, 0); title.Size = UDim2.new(1, -52, 1, 0); title.ZIndex = 34
    else
        header.Visible = false
    end

    local bodyTop = (config.HideHeader or name == "") and 0 or 45
    local body = make("Frame", {
        Name = "Body", BackgroundTransparency = 1, BorderSizePixel = 0,
        Position = UDim2.fromOffset(0, bodyTop), Size = UDim2.new(1, 0, 0, 0),
        ZIndex = 32,
    }, frame)
    pad(body, 10, 10, 0, 12)
    local lay = list(body, 8)
    local section = setmetatable({
        _tab = self, _frame = frame, _body = body, _layout = lay, _name = name,
        _side = sideName, _sectionOrder = self._order, _rowOrder = 0, _controls = {},
    }, Section)
    frame.LayoutOrder = section._sectionOrder
    table.insert(self._sections, section)

    lay:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() updateSectionHeight(section) end)
    local parent = self:_chooseParent(section)
    section._desktopParent = parent
    section._frame.Parent = parent
    if self._settingsBento then self:_moveSettingsSections() end
    updateSectionHeight(section)
    return section
end

function Tab:CreateButton(config) return self:_directSection():CreateButton(config) end
function Tab:CreateToggle(config) return self:_directSection():CreateToggle(config) end
function Tab:CreateDropdown(config) return self:_directSection():CreateDropdown(config) end
function Tab:CreateMultiDropdown(config) return self:_directSection():CreateMultiDropdown(config) end
function Tab:CreateTextbox(config) return self:_directSection():CreateTextbox(config) end
function Tab:CreateSlider(config) return self:_directSection():CreateSlider(config) end
function Tab:CreateColorpicker(config) return self:_directSection():CreateColorpicker(config) end
function Tab:CreateLabel(value) return self:_directSection():CreateLabel(value) end

local function addRow(section, name, iconName, height)
    section._rowOrder = (section._rowOrder or 0) + 1
    local row = make("Frame", {
        Name = "Row_" .. safeName(name), BackgroundColor3 = C.row, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, height or 48), LayoutOrder = section._rowOrder,
        ClipsDescendants = false, ZIndex = 60,
    }, section._body)
    corner(row, 13); outline(row, C.lineSoft, 0.30, 1)
    if iconName then packedIcon(row, iconName, UDim2.fromOffset(11, 11), UDim2.fromOffset(23, 23), C.muted, 63) end
    return row
end

function Section:CreateLabel(value)
    local row = addRow(self, "Label", nil, 38)
    local t = text(row, value, 12, C.secondary, false); t.Position = UDim2.fromOffset(12, 0); t.Size = UDim2.new(1, -24, 1, 0); t.ZIndex = 63
    return row
end

function Section:CreateButton(config)
    config = config or {}
    local name = config.Name or config.Title or "Button"
    local row = addRow(self, name, config.Icon, 48)
    local left = config.Icon and 42 or 14
    local t = text(row, name, 13, C.text, true); t.Position = UDim2.fromOffset(left, 0); t.Size = UDim2.new(1, -58, 1, 0); t.ZIndex = 64
    packedIcon(row, "chevron-right", UDim2.new(1, -31, 0.5, -9), UDim2.fromOffset(18, 18), C.muted, 64)
    local hit = hitButton(row, 90)
    hit.Activated:Connect(function() if config.Callback then task.spawn(config.Callback) end end)
    return {_frame = row}
end

function Section:CreateToggle(config)
    config = config or {}
    local name = config.Name or config.Title or "Toggle"
    local state = config.Default == true or config.Value == true
    local row = addRow(self, name, config.Icon, 50)
    local left = config.Icon and 42 or 14
    local title = text(row, name, 13, C.text, true); title.Position = UDim2.fromOffset(left, 0); title.Size = UDim2.new(1, -86, 1, 0); title.ZIndex = 64
    local track = make("Frame", {BackgroundColor3 = state and C.accent or C.rowPressed, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(48, 28), ZIndex = 64}, row)
    corner(track, 14)
    local knob = make("Frame", {BackgroundColor3 = C.text, BorderSizePixel = 0, Size = UDim2.fromOffset(22, 22), Position = state and UDim2.new(1, -25, 0.5, -11) or UDim2.fromOffset(3, 3), ZIndex = 65}, track)
    corner(knob, 11)
    local hit = hitButton(row, 90)
    local function set(v, emit)
        state = v == true
        tween(track, Motion.base, {BackgroundColor3 = state and C.accent or C.rowPressed})
        tween(knob, Motion.base, {Position = state and UDim2.new(1, -25, 0.5, -11) or UDim2.fromOffset(3, 3)})
        if emit and config.Callback then task.spawn(config.Callback, state) end
    end
    hit.Activated:Connect(function() set(not state, true) end)
    local ref = { _frame = row, Set = function(_, v) set(v, true) end, SetValue = function(_, v) set(v, true) end, Get = function() return state end }
    table.insert(self._controls, ref)
    return ref
end

local ActiveDropdown
local function getDropdownOverlay()
    local gui = UI._dropdownOverlay
    if gui and gui.Parent then return gui end
    gui = make("ScreenGui", {Name = "KhfreshDropdownOverlay", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 2147483647, ZIndexBehavior = Enum.ZIndexBehavior.Global}, GuiParent)
    UI._dropdownOverlay = gui
    return gui
end

local function closeDropdown()
    if ActiveDropdown and ActiveDropdown.Parent then pcall(function() ActiveDropdown:Destroy() end) end
    ActiveDropdown = nil
end

local function buildDropdownMenu(row, options, selected, multi, callback)
    closeDropdown()
    local overlay = getDropdownOverlay()
    local pos = row.AbsolutePosition
    local size = row.AbsoluteSize
    local vp = getViewport()
    local h = math.min(260, math.max(36, #options * 34 + 10))
    local menuW = math.min(320, math.max(190, size.X - 16))
    local x = math.clamp(pos.X + 8, 6, math.max(6, vp.X - menuW - 6))
    local belowY = pos.Y + size.Y + 4
    local y = belowY
    if y + h > vp.Y - 6 then y = math.max(6, pos.Y - h - 4) end
    local menu = make("ScrollingFrame", {
        Name = "DropdownMenu", BackgroundColor3 = C.shell, BorderSizePixel = 0,
        Position = UDim2.fromOffset(x, y),
        Size = UDim2.fromOffset(menuW, h),
        CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollBarThickness = 2, ScrollBarImageColor3 = C.muted, ZIndex = 5000,
    }, overlay)
    corner(menu, 12); outline(menu, C.line, 0.10, 1); pad(menu, 5, 5, 5, 5)
    local lay = list(menu, 4)
    ActiveDropdown = menu
    for _, opt in ipairs(options) do
        local rowBtn = make("TextButton", {Text = "", BackgroundColor3 = C.row, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 34), AutoButtonColor = false, ZIndex = 5001}, menu)
        corner(rowBtn, 9)
        local label = text(rowBtn, opt, 11, C.secondary, false); label.Position = UDim2.fromOffset(10, 0); label.Size = UDim2.new(1, -20, 1, 0); label.ZIndex = 5003
        if multi and selected[opt] then
            packedIcon(rowBtn, "check", UDim2.new(1, -27, 0.5, -8), UDim2.fromOffset(16, 16), C.secondary, 5004)
        end
        rowBtn.Activated:Connect(function()
            if multi then
                selected[opt] = not selected[opt]
                if callback then task.spawn(callback, selected) end
                buildDropdownMenu(row, options, selected, multi, callback)
            else
                closeDropdown()
                if callback then task.spawn(callback, opt) end
            end
        end)
    end
    return menu
end

function Section:CreateDropdown(config)
    config = config or {}
    local name = config.Name or config.Title or "Dropdown"
    local rawOptions = config.Options or config.Values or {}
    local options = {}
    for _, v in ipairs(rawOptions) do
        if type(v) == "table" then v = v.Title or v.Name or v.Value or v.Text or v[1] end
        if v ~= nil then options[#options + 1] = tostring(v) end
    end
    local selected = tostring(config.Default or config.Value or options[1] or "Select")
    local row = addRow(self, name, config.Icon, 52)
    local left = config.Icon and 42 or 14
    local title = text(row, name, 12, C.secondary, true); title.Position = UDim2.fromOffset(left, 0); title.Size = UDim2.new(0.42, -left, 1, 0); title.ZIndex = 64
    local value = text(row, selected, 12, C.text, false); value.Position = UDim2.new(0.42, 0, 0, 0); value.Size = UDim2.new(0.58, -48, 1, 0); value.TextXAlignment = Enum.TextXAlignment.Right; value.ZIndex = 64
    packedIcon(row, "chevron-down", UDim2.new(1, -32, 0.5, -8), UDim2.fromOffset(17, 17), C.muted, 65)
    local hit = hitButton(row, 90)
    local open = false
    local function choose(v)
        selected = tostring(v); value.Text = selected
        if config.Callback then task.spawn(config.Callback, selected) end
    end
    hit.Activated:Connect(function()
        open = not open
        if open then
            buildDropdownMenu(row, options, {}, false, function(v) choose(v) end)
        else
            closeDropdown()
        end
    end)
    return { _frame = row, Set = function(_, v) choose(v) end, SetValue = function(_, v) choose(v) end, Get = function() return selected end }
end

function Section:CreateMultiDropdown(config)
    config = config or {}
    local name = config.Name or config.Title or "Multi Dropdown"
    local rawOptions = config.Options or config.Values or {}
    local options = {}
    for _, v in ipairs(rawOptions) do
        if type(v) == "table" then v = v.Title or v.Name or v.Value or v.Text or v[1] end
        if v ~= nil then options[#options + 1] = tostring(v) end
    end
    local selected = {}
    if type(config.Default) == "table" then for _, v in ipairs(config.Default) do selected[tostring(v)] = true end end
    local row = addRow(self, name, config.Icon, 52)
    local left = config.Icon and 42 or 14
    local title = text(row, name, 12, C.secondary, true); title.Position = UDim2.fromOffset(left, 0); title.Size = UDim2.new(0.42, -left, 1, 0); title.ZIndex = 64
    local value = text(row, "None", 11, C.text, false); value.Position = UDim2.new(0.42, 0, 0, 0); value.Size = UDim2.new(0.58, -48, 1, 0); value.TextXAlignment = Enum.TextXAlignment.Right; value.ZIndex = 64
    packedIcon(row, "chevron-down", UDim2.new(1, -32, 0.5, -8), UDim2.fromOffset(17, 17), C.muted, 65)
    local function updateLabel()
        local arr = {}
        for _, v in ipairs(options) do if selected[v] then arr[#arr + 1] = v end end
        value.Text = #arr == 0 and "None" or (#arr <= 2 and table.concat(arr, ", ") or (tostring(#arr) .. " selected"))
    end
    updateLabel()
    local hit = hitButton(row, 90)
    hit.Activated:Connect(function()
        if ActiveDropdown then closeDropdown() end
        buildDropdownMenu(row, options, selected, true, function(sel)
            local arr = {}
            for _, v in ipairs(options) do if sel[v] then arr[#arr + 1] = v end end
            updateLabel()
            if config.Callback then task.spawn(config.Callback, arr) end
        end)
    end)
    return {
        _frame = row,
        Set = function(_, v)
            if type(v) == "table" then
                table.clear(selected); for _, x in ipairs(v) do selected[tostring(x)] = true end; updateLabel()
            end
        end,
        Get = function() local out = {}; for _, v in ipairs(options) do if selected[v] then out[#out + 1] = v end end; return out end,
    }
end

function Section:CreateTextbox(config)
    config = config or {}
    local name = config.Name or config.Title or "Input"
    local row = addRow(self, name, config.Icon, 52)
    local left = config.Icon and 42 or 14
    local title = text(row, name, 12, C.secondary, true); title.Position = UDim2.fromOffset(left, 0); title.Size = UDim2.new(0.40, -left, 1, 0); title.ZIndex = 64
    local box = make("TextBox", {
        BackgroundColor3 = C.shell, BorderSizePixel = 0, Text = tostring(config.Default or config.Value or ""),
        PlaceholderText = tostring(config.Placeholder or ""), PlaceholderColor3 = C.muted, TextColor3 = C.text,
        TextSize = 12, Font = Enum.Font.Gotham, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(0.58, -8, 0, 34), Position = UDim2.new(0.40, 0, 0.5, -17), ZIndex = 68,
    }, row)
    corner(box, 10); outline(box, C.lineSoft, 0.16, 1); pad(box, 10, 10, 0, 0)
    local function emit() if config.Callback then task.spawn(config.Callback, box.Text) end end
    box.FocusLost:Connect(emit)
    return { _frame = row, _input = box, Set = function(_, v) box.Text = tostring(v or ""); emit() end, SetValue = function(_, v) box.Text = tostring(v or ""); emit() end, Get = function() return box.Text end }
end

function Section:CreateSlider(config)
    config = config or {}
    local name = config.Name or config.Title or "Slider"
    local min = tonumber(config.Min or config.Minimum or 0) or 0
    local max = tonumber(config.Max or config.Maximum or 100) or 100
    if max <= min then max = min + 1 end
    local current = math.clamp(tonumber(config.Default or config.Value or min) or min, min, max)
    local row = addRow(self, name, config.Icon, 66)
    local left = config.Icon and 42 or 14
    local title = text(row, name, 12, C.secondary, true); title.Position = UDim2.fromOffset(left, 4); title.Size = UDim2.new(0.55, -left, 0, 24); title.ZIndex = 64
    local value = text(row, tostring(current), 11, C.text, true); value.Position = UDim2.new(1, -70, 0, 4); value.Size = UDim2.fromOffset(58, 24); value.TextXAlignment = Enum.TextXAlignment.Right; value.ZIndex = 64
    local track = make("Frame", {BackgroundColor3 = C.shell, BorderSizePixel = 0, Position = UDim2.new(0, 14, 1, -22), Size = UDim2.new(1, -28, 0, 6), ZIndex = 65}, row)
    corner(track, 99)
    local pct = (current - min) / (max - min)
    local fill = make("Frame", {BackgroundColor3 = C.accent, BorderSizePixel = 0, Size = UDim2.new(pct, 0, 1, 0), ZIndex = 66}, track)
    corner(fill, 99)
    local hit = make("TextButton", {Text = "", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 32), Position = UDim2.new(0, 0, 0.5, -16), AutoButtonColor = false, ZIndex = 70}, track)
    local dragging = false
    local function applyX(x, emit)
        local p = math.clamp((x - track.AbsolutePosition.X) / math.max(1, track.AbsoluteSize.X), 0, 1)
        current = math.floor((min + (max - min) * p) + 0.5)
        value.Text = tostring(current); fill.Size = UDim2.new(p, 0, 1, 0)
        if emit and config.Callback then task.spawn(config.Callback, current) end
    end
    hit.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        dragging = true; applyX(input.Position.X, true)
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then applyX(input.Position.X, true) end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
    end)
    return { _frame = row, Set = function(_, v) applyX(track.AbsolutePosition.X + track.AbsoluteSize.X * math.clamp((tonumber(v) or min - min) / (max - min), 0, 1), true) end, Get = function() return current end }
end

