function Tab:CreateStatRow(items)
    local row = make("Frame", {BackgroundColor3 = C.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 48), LayoutOrder = 9998, ZIndex = 30}, self._listHost or self._grid)
    corner(row, 14); outline(row, C.lineSoft, 0.2, 1)
    local x = 12
    for _, item in ipairs(items or {}) do
        local val = text(row, tostring(item.Value or item[2] or "-"), 12, C.text, true); val.Position = UDim2.fromOffset(x, 0); val.Size = UDim2.new(0, 80, 1, 0)
        x = x + 90
    end
    return row
end
function Tab:CreateFeaturedCard(config)
    config = config or {}
    local row = make("Frame", {BackgroundColor3 = C.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 72), LayoutOrder = 9999, ZIndex = 30}, self._listHost or self._grid)
    corner(row, 16); outline(row, C.lineSoft, 0.2, 1)
    local t = text(row, config.Title or "Featured", 14, C.text, true); t.Position = UDim2.fromOffset(14, 9); t.Size = UDim2.new(1, -28, 0, 22)
    local d = text(row, config.Subtitle or config.Desc or "", 11, C.muted, false); d.Position = UDim2.fromOffset(14, 34); d.Size = UDim2.new(1, -28, 0, 22)
    if config.Callback then hitButton(row, 90).Activated:Connect(config.Callback) end
    return row
