function Tab:CreateActionRow(config)
    return self:CreateFeaturedCard(config)
end
function Tab:CreateCardGroup(config)
    return self:CreateFeaturedCard(config)
end

function Window:ApplyTheme()
    if self._shell then self._shell.BackgroundColor3 = C.canvas end
    if self._top then self._top.BackgroundColor3 = C.header end
    if self._rail then self._rail.BackgroundColor3 = C.rail end
    for _, tab in ipairs(self._tabs) do
        if tab._btn then tab._btn.BackgroundColor3 = tab == self._selected and C.accentSoft or C.row end
        if tab._icon then iconSetColor(tab._icon, tab == self._selected and C.secondary or C.muted) end
    end
end

return UI
